<?php
declare(strict_types=1);
if(!defined('HOGAR_INTERNAL')){http_response_code(404);exit;}
$db->exec('CREATE TABLE IF NOT EXISTS property_metrics(property_id TEXT NOT NULL REFERENCES properties(id) ON DELETE CASCADE,day TEXT NOT NULL,views INTEGER NOT NULL DEFAULT 0,contacts INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(property_id,day));CREATE TABLE IF NOT EXISTS property_metric_seen(property_id TEXT NOT NULL REFERENCES properties(id) ON DELETE CASCADE,day TEXT NOT NULL,kind TEXT NOT NULL,visitor TEXT NOT NULL,PRIMARY KEY(property_id,day,kind,visitor));');
function metricDay(): string {return (new DateTimeImmutable('now',new DateTimeZone('America/Mexico_City')))->format('Y-m-d');}
function metricValues(string $id): array {$v=query('SELECT COALESCE(SUM(views),0) AS views,COALESCE(SUM(contacts),0) AS contacts FROM property_metrics WHERE property_id=?',[$id])->fetch();return ['views'=>(int)$v['views'],'contacts'=>(int)$v['contacts'],'favorites'=>(int)query('SELECT COUNT(*) FROM property_favorites WHERE property_id=?',[$id])->fetchColumn()];}
function handlePropertyStats(string $action,string $method,array $input): void {
 if($action==='property-metric'&&$method==='POST'){
  $id=$input['id']??'';$kind=$input['kind']??'';if(!is_string($id)||!preg_match('/^[a-f0-9]{24}$/D',$id)||!in_array($kind,['view','contact'],true))fail('Evento inválido.',422);
  $p=selectProperty($id);if(!$p||$p['status']!=='active'||$p['owner_status']!=='active')fail('Anuncio no disponible.',404);$u=user();if((int)($u['id']??0)===(int)$p['user_id']||isSuperadmin($u))reply(['recorded'=>false]);
  limitRate('property-metric',500,3600);global $db;$day=metricDay();$visitor=hash('sha256',session_id().'|'.$day);$db->beginTransaction();try{query('DELETE FROM property_metric_seen WHERE day<=?',[(new DateTimeImmutable('-2 days',new DateTimeZone('America/Mexico_City')))->format('Y-m-d')]);$q=query('INSERT OR IGNORE INTO property_metric_seen(property_id,day,kind,visitor) VALUES(?,?,?,?)',[$id,$day,$kind,$visitor]);$recorded=$q->rowCount()>0;if($recorded){$field=$kind==='view'?'views':'contacts';query('INSERT INTO property_metrics(property_id,day,'.$field.') VALUES(?,?,1) ON CONFLICT(property_id,day) DO UPDATE SET '.$field.'='.$field.'+1',[$id,$day]);}$db->commit();}catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}reply(['recorded'=>$recorded]);
 }
 if($action==='property-stats'&&$method==='GET'){$u=requireUser();$id=$_GET['id']??'';if(!is_string($id))fail('Anuncio no disponible.',404);$p=query('SELECT id,title FROM properties WHERE id=? AND user_id=?',[$id,$u['id']])->fetch();if(!$p)fail('Anuncio no disponible.',404);reply(['property'=>$p,'metrics'=>metricValues($id)]);}
 if($action==='admin-statistics'&&$method==='GET'){$u=requireUser();if(!isSuperadmin($u))fail('Acceso reservado.',403);$page=max(1,min(10000,(int)($_GET['page']??1)));$total=(int)query('SELECT COUNT(*) FROM properties')->fetchColumn();$rows=query('SELECT id,title,operation,status FROM properties ORDER BY created DESC,id DESC LIMIT 20 OFFSET '.(($page-1)*20))->fetchAll();foreach($rows as &$row)$row['metrics']=metricValues($row['id']);unset($row);$v=query('SELECT COALESCE(SUM(views),0) AS views,COALESCE(SUM(contacts),0) AS contacts FROM property_metrics')->fetch();reply(['items'=>$rows,'metrics'=>['views'=>(int)$v['views'],'contacts'=>(int)$v['contacts'],'favorites'=>(int)query('SELECT COUNT(*) FROM property_favorites')->fetchColumn()],'page'=>$page,'pages'=>(int)ceil($total/20)]);}
}
